package com.bemodel.compute;
import com.bemodel.common.BizException;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.ObjectProvider;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@EnabledIfEnvironmentVariable(named="COMPUTE_ONTOLOGY_MYSQL_URL",matches="jdbc:mysql:.*")
@org.junit.jupiter.api.parallel.Execution(org.junit.jupiter.api.parallel.ExecutionMode.CONCURRENT)
class ComputePreemptionDatabaseTest {
 ComputeWorkflowDatabaseTest f;ComputeRecoverySpecService specs;long request;
 @BeforeEach void setup()throws Exception{f=new ComputeWorkflowDatabaseTest();f.setup();var provider=mock(ObjectProvider.class);when(provider.getIfAvailable()).thenReturn(f.sim);f.wf.preemption=new ComputePreemptionWorkflow(f.store,f.actions,f.projection,f.queue,f.json,provider);f.wf.preemption.decisions=f.reservations;f.wf.preemption.observationTtl=120;specs=new ComputeRecoverySpecService(f.store);
  f.j.update("UPDATE gpu_group SET pending_allocation_id=NULL WHERE id=2");f.j.update("UPDATE gpu_allocation SET status='CANCELLED',closed_at=UTC_TIMESTAMP(6),close_reason='ISOLATED_FIXTURE' WHERE id=1");
 }
 @AfterEach void cleanup()throws Exception{if(f!=null)f.cleanup();}
 long register(long vram){return ((Number)specs.register(2,f.json.createObjectNode().put("revisionId",2).put("vramBytesPerGpu",vram).put("gpuInterconnect","NONE").put("harnessTeamId",1).put("declaration","隔离演示：DEMO 团队承担 harness，资源由部署负责人显式声明")).get("id")).longValue();}
 long create(boolean declare){if(declare)register(1073741824);f.fresh();var b=f.json.createObjectNode().put("employeeId",1).put("projectId",1).put("taskTypeId",1).put("clientRequestKey",UUID.randomUUID().toString()).put("requestedGpuCount",2);b.putObject("requestedResourceSpec").put("memoryBytes",1073741824).put("vramBytesPerGpu",1073741824).put("gpuInterconnect","NONE");b.putObject("launchSpec").put("imageRef","demo/train");request=f.requests.submit(b).id();var proposal=f.json.createObjectNode().put("nodeKey","a800-demo").put("requestId",request);f.queue.enqueue(proposal);var r=f.reservations.reserve(proposal);assertEquals("RESERVED",r.outcome(),r.toString());return ((Number)f.wf.create(r.receipt().id()).get("id")).longValue();}
 Map<String,Object> detail(long id){return f.wf.detail(id);}String step(long id){return f.step(id);}
 void next(long id,String expected){f.wf.advance(id);assertEquals(expected,step(id),detail(id).toString());}
 void reach(long id,String goal){for(int i=0;i<24&&!goal.equals(step(id));i++){String old=step(id);f.wf.advance(id);if(old.equals(step(id)))fail("Unexpected wait: "+detail(id));}assertEquals(goal,step(id),detail(id).toString());}
 void scenario(long id,String mode){var w=detail(id);f.sim.scenario(f.json.createObjectNode().put("operationKey","workflow:"+id+":"+w.get("step")+":"+w.get("row_version")).put("mode",mode));}
 long lastAction(long id,String type){return f.j.queryForObject("SELECT id FROM execution_action WHERE workflow_run_id=? AND action_type=? ORDER BY id DESC LIMIT 1",Long.class,id,type);}
 void restored(long id){reach(id,"DONE");assertEquals("RESTORED",detail(id).get("recovery_state"));assertTrue(f.sim.state("a800-demo").path("deployments").path("2").path("acceptingTraffic").asBoolean());assertEquals(2,f.j.queryForObject("SELECT h.deployment_revision_id FROM gpu_group g JOIN hold_period h ON h.id=g.current_hold_id WHERE g.id=2 AND h.ended_at IS NULL",Long.class));if(detail(id).get("last_closure_decision_id")!=null){long d=((Number)detail(id).get("last_closure_decision_id")).longValue();assertEquals("RESTORE",f.j.queryForObject("SELECT outcome FROM decision WHERE id=?",String.class,d));assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM rule_check c JOIN rule_version v ON v.id=c.rule_version_id WHERE c.decision_id=? AND v.rule_code='R-06'",Integer.class,d));}}
 void requestStop(long id){reach(id,"RUNNING");f.wf.stop(id,false);reach(id,"RESTORE_CHECK");}

 @Test void normalRecoveryPinsActualRevisionAndDeclarationDespiteNewConfiguration(){long id=create(true);long spec=((Number)detail(id).get("restore_spec_id")).longValue();register(90L*1073741824);long newer=ComputeReleaseBridge.insert(f.j,"INSERT INTO deployment_revision(deployment_id,version,image_ref,command_args,mounts,health_check,memory_bytes) VALUES(2,2,'demo/new','[]','[]','{}',1024)");f.j.update("UPDATE deployment SET current_revision_id=? WHERE id=2",newer);
  assertThrows(Exception.class,()->f.j.update("UPDATE deployment_revision SET memory_bytes=1 WHERE id=2"));assertThrows(Exception.class,()->f.j.update("UPDATE deployment_recovery_spec SET vram_bytes_per_gpu=1 WHERE id=?",spec));requestStop(id);restored(id);assertEquals(spec,((Number)detail(id).get("restore_spec_id")).longValue());assertEquals(newer,f.j.queryForObject("SELECT current_revision_id FROM deployment WHERE id=2",Long.class));
  long job=((Number)detail(id).get("job_id")).longValue();assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM gpu_allocation WHERE job_id=?",Integer.class,job));f.wf.advance(id);assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM execution_action WHERE workflow_run_id=? AND action_type='START_JOB'",Integer.class,id));
 }
 @Test void missingRequirementsBlockBeforeNotification(){assertThrows(BizException.class,()->create(false));assertEquals(0,f.j.queryForObject("SELECT COUNT(*) FROM execution_action",Integer.class));}
 @Test void failedNotificationCancelsWithoutDraining(){notifyFailure("FAILURE");}
 @Test void lostNotificationReceiptCancelsWithoutDraining(){notifyFailure("TIMEOUT");}
 void notifyFailure(String mode){long id=create(true);scenario(id,mode);next(id,"DONE");assertEquals("CANCELLED",f.allocation(id));assertEquals(0,f.j.queryForObject("SELECT COUNT(*) FROM execution_action WHERE workflow_run_id=? AND action_type='DRAIN'",Integer.class,id));assertTrue(f.sim.state("a800-demo").path("deployments").path("2").path("acceptingTraffic").asBoolean());}
 @Test void inflightWaitAndCancellationResumeTheOriginalDeployment(){long id=create(true);var body=f.json.createObjectNode();body.putArray("deployments").addObject().put("id",2).put("inFlightRequests",3);f.sim.configure("a800-demo",body);reach(id,"WAIT_INFLIGHT");f.wf.advance(id);assertEquals("WAIT_INFLIGHT",step(id));assertTrue(detail(id).get("last_error").toString().contains("WAIT_INFLIGHT"));f.wf.stop(id,true);restored(id);assertEquals("CANCELLED",f.allocation(id));assertEquals(0,f.j.queryForObject("SELECT COUNT(*) FROM execution_action WHERE workflow_run_id=? AND action_type='STOP'",Integer.class,id));}
 @Test void unknownStopCannotHandoverAndCancellationStillRestores(){long id=create(true);reach(id,"STOP");scenario(id,"TIMEOUT");next(id,"STOP");assertEquals("PENDING",f.allocation(id));assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM hold_period WHERE id=2 AND ended_at IS NULL",Integer.class));f.wf.stop(id,true);restored(id);assertEquals("CANCELLED",f.allocation(id));assertEquals(0,f.j.queryForObject("SELECT COUNT(*) FROM execution_action WHERE workflow_run_id=? AND action_type='START_JOB'",Integer.class,id));}
 @Test void handoverRollbackAndRestartDoNotDoubleActivate(){long id=create(true);reach(id,"HANDOVER");f.j.execute("CREATE TRIGGER test_b_handover BEFORE INSERT ON resource_event FOR EACH ROW BEGIN IF NEW.event_type='WORKFLOW_PREEMPTION_HANDOVER' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='test'; END IF; END");try{f.wf.advance(id);assertEquals("PENDING",f.allocation(id));assertEquals("HANDOVER",step(id));assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM hold_period WHERE id=2 AND ended_at IS NULL",Integer.class));}finally{f.j.execute("DROP TRIGGER test_b_handover");}
  var previous=f.wf.preemption;f.wf=new ComputeWorkflowService(f.store,f.actions,f.projection,f.json);f.wf.preemption=previous;f.j.update("UPDATE workflow_run SET lease_token='crashed',lease_until='2020-01-01' WHERE id=?",id);requestStop(id);restored(id);
 }
 @Test void failedTrainingStartKeepsResponsibilityThroughCompensation(){long id=create(true);reach(id,"START_JOB");scenario(id,"FAILURE");next(id,"STOP_JOB");assertEquals("OCCUPIED",f.allocation(id));assertEquals("OWED",detail(id).get("recovery_state"));restored(id);assertEquals("FAILED",f.j.queryForObject("SELECT b.status FROM compute_job b JOIN workflow_run w ON w.job_id=b.id WHERE w.id=?",String.class,id));}
 @Test void cancelDuringUnknownTrainingStartResolvesOriginalResult(){long id=create(true);reach(id,"START_JOB");scenario(id,"TIMEOUT");next(id,"START_JOB");f.wf.stop(id,true);assertEquals("OCCUPIED",f.allocation(id));restored(id);assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM execution_action WHERE workflow_run_id=? AND action_type='START_JOB'",Integer.class,id));}
 @Test void failedTrainingStopDoesNotReleaseAndUsesExistingSafeRetry(){long id=create(true);reach(id,"RUNNING");f.wf.stop(id,false);reach(id,"STOP_JOB");scenario(id,"FAIL_THEN_SUCCESS");next(id,"STOP_JOB");assertEquals("OCCUPIED",f.allocation(id));assertTrue(detail(id).get("last_error")==null||detail(id).get("last_error").toString().contains("STOP"));f.actions.retry(lastAction(id,"STOP_JOB"));restored(id);}
 @Test void restorationWaitsForCapacityAndWholeGroupHealth(){long id=create(true);requestStop(id);long capacity=f.j.queryForObject("SELECT memory_capacity_bytes FROM compute_node WHERE id=1",Long.class);f.j.update("UPDATE compute_node SET memory_capacity_bytes=memory_reserved_bytes+? WHERE id=1",42L*1073741824);next(id,"RESTORE_CHECK");assertEquals("WAITING",detail(id).get("recovery_state"));assertEquals("RELEASED",f.allocation(id));assertEquals(0,f.j.queryForObject("SELECT COUNT(*) FROM execution_action WHERE workflow_run_id=? AND action_type='RESTORE'",Integer.class,id));f.j.update("UPDATE compute_node SET memory_capacity_bytes=? WHERE id=1",capacity);var p=f.json.createObjectNode();p.putArray("gpus").addObject().put("id",5).put("healthy",false);f.sim.configure("a800-demo",p);next(id,"RESTORE_CHECK");p.withArray("gpus").removeAll().addObject().put("id",5).put("healthy",true);f.sim.configure("a800-demo",p);restored(id);}
 @Test void restoreFailureKeepsItsCapacityReservationAndCanBeRetried(){long id=create(true);requestStop(id);reach(id,"RESTORE");scenario(id,"FAIL_THEN_SUCCESS");next(id,"RESTORE");assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM compute_restore_reservation WHERE workflow_id=?",Integer.class,id));f.actions.retry(lastAction(id,"RESTORE"));restored(id);assertEquals(0,f.j.queryForObject("SELECT COUNT(*) FROM compute_restore_reservation WHERE workflow_id=?",Integer.class,id));}
 @Test void unhealthyRestoredDeploymentNeverReceivesTraffic(){long id=create(true);requestStop(id);reach(id,"HEALTH_CHECK");var p=f.json.createObjectNode();p.putArray("deployments").addObject().put("id",2).put("healthy",false);f.sim.configure("a800-demo",p);next(id,"HEALTH_CHECK");assertFalse(f.sim.state("a800-demo").path("deployments").path("2").path("acceptingTraffic").asBoolean());p.withArray("deployments").removeAll().addObject().put("id",2).put("healthy",true);f.sim.configure("a800-demo",p);f.actions.retry(lastAction(id,"HEALTH_CHECK"));restored(id);}
 @Test void pendingHandoffCandidateBlocksRestoreUntilExplicitReevaluation(){long id=create(true);requestStop(id);var b=f.json.createObjectNode().put("employeeId",1).put("projectId",1).put("taskTypeId",1).put("clientRequestKey",UUID.randomUUID().toString()).put("requestedGpuCount",2);b.putObject("requestedResourceSpec").put("memoryBytes",1024).put("vramBytesPerGpu",1073741824).put("gpuInterconnect","NONE");b.putObject("launchSpec").put("imageRef","demo/next");long candidate=f.requests.submit(b).id();f.queue.enqueue(f.json.createObjectNode().put("nodeKey","a800-demo").put("requestId",candidate));next(id,"RESTORE_CHECK");assertTrue(detail(id).get("last_error").toString().contains("QUEUE_ARBITRATION_REQUIRED"));assertEquals(0,f.j.queryForObject("SELECT COUNT(*) FROM compute_restore_reservation WHERE workflow_id=?",Integer.class,id));f.requests.cancel(candidate);restored(id);}
 @Test void concurrentAdvanceAndDuplicateReceiptDoNotRepeatHandoverOrStart()throws Exception{long id=create(true);reach(id,"HANDOVER");try(var threads=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=threads.submit(()->f.wf.advance(id));var b=threads.submit(()->f.wf.advance(id));a.get();b.get();}reach(id,"RUNNING");long start=lastAction(id,"START_JOB");f.actions.reconcile(start);f.actions.reconcile(start);assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM hold_period h JOIN gpu_allocation a ON a.id=h.allocation_id JOIN workflow_run w ON w.job_id=a.job_id WHERE w.id=?",Integer.class,id));assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM execution_action WHERE workflow_run_id=? AND action_type='START_JOB'",Integer.class,id));requestStop(id);restored(id);}
 @Test void restorationCapacityReservationIsCountedByOtherGroupRequests(){long id=create(true);requestStop(id);reach(id,"RESTORE");var body=f.json.createObjectNode().put("employeeId",1).put("projectId",1).put("taskTypeId",1).put("clientRequestKey",UUID.randomUUID().toString()).put("requestedGpuCount",1);body.putObject("requestedResourceSpec").put("memoryBytes",70L*1073741824).put("vramBytesPerGpu",1073741824).put("gpuInterconnect","NONE");body.putObject("launchSpec").put("imageRef","demo/cross-group");long candidate=f.requests.submit(body).id();f.sim.observe("a800-demo",f.json.createObjectNode().put("validForSeconds",120));var proposal=f.json.createObjectNode().put("nodeKey","a800-demo").put("requestId",candidate);f.queue.enqueue(proposal);var r=f.reservations.reserve(proposal);assertEquals("WAITING",r.outcome(),r.toString());assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM compute_restore_reservation WHERE workflow_id=?",Integer.class,id));restored(id);}
 @Test void newHealthOrCapacityFailureAfterRestoreReservationPreventsDispatch(){long id=create(true);requestStop(id);reach(id,"RESTORE");long capacity=f.j.queryForObject("SELECT memory_capacity_bytes FROM compute_node WHERE id=1",Long.class);f.j.update("UPDATE compute_node SET memory_capacity_bytes=memory_reserved_bytes+? WHERE id=1",42L*1073741824);next(id,"RESTORE");assertTrue(detail(id).get("last_error").toString().contains("WAIT_RESTORE_RESOURCES"));f.j.update("UPDATE compute_node SET memory_capacity_bytes=? WHERE id=1",capacity);var p=f.json.createObjectNode();p.putArray("gpus").addObject().put("id",5).put("healthy",false);f.sim.configure("a800-demo",p);next(id,"RESTORE");assertEquals(0,f.j.queryForObject("SELECT COUNT(*) FROM execution_action WHERE workflow_run_id=? AND action_type='RESTORE'",Integer.class,id));p.withArray("gpus").removeAll().addObject().put("id",5).put("healthy",true);f.sim.configure("a800-demo",p);restored(id);}
 @Test void originalStopFailureKeepsActualHoldUntilSafeRetry(){long id=create(true);reach(id,"STOP");scenario(id,"FAIL_THEN_SUCCESS");next(id,"STOP");assertEquals("PENDING",f.allocation(id));assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM hold_period WHERE id=2 AND ended_at IS NULL",Integer.class));assertTrue(detail(id).get("last_error").toString().contains("STOP_FAILED"));f.actions.retry(lastAction(id,"STOP"));requestStop(id);restored(id);}
}
